import * as THREE from 'three';

export const uTime = { value: 0 };

export function makeRng(seed: number): () => number {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function ripplePhase(x: number, z: number): number {
  return (
    (x * 0.8 + z * 0.45) * 4.2 +
    1.6 * Math.sin(z * 0.5 + x * 0.2) +
    0.8 * Math.sin(x * 0.9 - z * 0.3)
  );
}

export function ripple(x: number, z: number): number {
  return Math.sin(ripplePhase(x, z));
}

/** Height of the sand surface at (x, z). */
export function terrainHeight(x: number, z: number): number {
  const dune =
    0.3 * Math.sin(x * 0.13 + 1.0) * Math.sin(z * 0.11) +
    0.12 * Math.sin(x * 0.3 + z * 0.2);
  const r = Math.hypot(x, z);
  const rippleAmp = 0.045 * Math.min(1, 0.4 + r * 0.1);
  return dune + rippleAmp * ripple(x, z);
}

export interface PatchOptions {
  key: string;
  caustic?: number;
  swayAmp?: number;
  wag?: boolean;
}

const f = (n: number): string => n.toFixed(4);

const CAUSTIC_GLSL = /* glsl */ `
float causticPattern(vec2 uv, float t) {
  vec2 p = mod(uv * 6.28318530718, 6.28318530718) - 250.0;
  vec2 i = p;
  float c = 1.0;
  float inten = 0.005;
  for (int n = 0; n < 4; n++) {
    float tt = t * (1.0 - (3.5 / float(n + 1)));
    i = p + vec2(cos(tt - i.x) + sin(tt + i.y), sin(tt - i.y) + cos(tt + i.x));
    c += 1.0 / length(vec2(p.x / (sin(i.x + tt) / inten), p.y / (cos(i.y + tt) / inten)));
  }
  c /= 4.0;
  c = 1.17 - pow(c, 1.4);
  return clamp(pow(abs(c), 8.0), 0.0, 1.5);
}
`;

/** Adds drifting caustics, plant sway and fish tail wag to a standard material. */
export function patchMaterial(mat: THREE.Material, opts: PatchOptions): void {
  const caustic = opts.caustic ?? 0;
  const sway = opts.swayAmp ?? 0;
  const wag = opts.wag ?? false;
  mat.customProgramCacheKey = () => `patched-${opts.key}`;
  mat.onBeforeCompile = (shader) => {
    shader.uniforms.uTime = uTime;

    let vtxCommon = `#include <common>
uniform float uTime;
varying vec3 vWPos;
`;
    if (wag) vtxCommon += 'attribute float aPhase;\n';

    let vtxBegin = '#include <begin_vertex>\n';
    if (sway > 0) {
      vtxBegin += `
{
#ifdef USE_INSTANCING
  vec3 swP = vec3(instanceMatrix[3]);
#else
  vec3 swP = modelMatrix[3].xyz;
#endif
  float swH = max(transformed.y, 0.0);
  float swPh = swP.x * 0.7 + swP.z * 0.9;
  float swK = ${f(sway)} * swH * swH;
  transformed.x += sin(uTime * 1.4 + swPh + swH * 1.5) * swK;
  transformed.z += cos(uTime * 1.1 + swPh * 1.3 + swH * 1.2) * swK * 0.7;
}
`;
    }
    if (wag) {
      vtxBegin += `
{
  float wg = sin(uTime * 9.0 + aPhase - transformed.z * 4.0);
  float wk = smoothstep(0.3, -1.4, transformed.z);
  transformed.x += wg * 0.2 * wk;
  transformed.z += 0.0;
}
`;
    }

    const vtxProject = `#include <project_vertex>
{
  vec4 cwp = vec4(transformed, 1.0);
#ifdef USE_INSTANCING
  cwp = instanceMatrix * cwp;
#endif
  vWPos = (modelMatrix * cwp).xyz;
}
`;

    shader.vertexShader = shader.vertexShader
      .replace('#include <common>', vtxCommon)
      .replace('#include <begin_vertex>', vtxBegin)
      .replace('#include <project_vertex>', vtxProject);

    const fragCommon = `#include <common>
uniform float uTime;
varying vec3 vWPos;
${CAUSTIC_GLSL}
`;
    let fragOut = '#include <opaque_fragment>';
    if (caustic > 0) {
      fragOut = `
{
  vec2 cuv = vWPos.xz * 0.11;
  float cA = causticPattern(cuv, uTime * 0.35);
  float cB = causticPattern(cuv * 1.37 + 3.1, uTime * 0.27 + 5.0);
  float cc = 0.65 * cA + 0.5 * cB;
  float depthFade = exp(-max(vWPos.y, 0.0) * 0.18);
  outgoingLight += diffuseColor.rgb * vec3(0.75, 1.0, 0.9) * cc * ${f(caustic)} * depthFade;
}
#include <opaque_fragment>`;
    }
    shader.fragmentShader = shader.fragmentShader
      .replace('#include <common>', fragCommon)
      .replace('#include <opaque_fragment>', fragOut);
  };
}

import * as THREE from 'three';
import { mergeGeometries, mergeVertices } from 'three/examples/jsm/utils/BufferGeometryUtils.js';
import { makeRng, patchMaterial, ripple, terrainHeight } from './util';

const UP = new THREE.Vector3(0, 1, 0);

function setConstantColor(geo: THREE.BufferGeometry, factor: number): void {
  const n = geo.getAttribute('position').count;
  const arr = new Float32Array(n * 3).fill(factor);
  geo.setAttribute('color', new THREE.BufferAttribute(arr, 3));
}

/* ---------- seabed ---------- */

export function createSeabed(): THREE.Mesh {
  const size = 80;
  const seg = 340;
  const geo = new THREE.PlaneGeometry(size, size, seg, seg);
  geo.rotateX(-Math.PI / 2);
  const pos = geo.getAttribute('position');
  const colors = new Float32Array(pos.count * 3);
  const rng = makeRng(7);
  for (let i = 0; i < pos.count; i++) {
    const x = pos.getX(i);
    const z = pos.getZ(i);
    pos.setY(i, terrainHeight(x, z));
    const r = ripple(x, z);
    const grain = 0.94 + rng() * 0.06;
    const k = (0.86 + 0.14 * r) * grain;
    colors[i * 3] = 0.86 * k;
    colors[i * 3 + 1] = 0.78 * k;
    colors[i * 3 + 2] = 0.58 * k;
  }
  geo.setAttribute('color', new THREE.BufferAttribute(colors, 3));
  geo.computeVertexNormals();
  const mat = new THREE.MeshStandardMaterial({ vertexColors: true, roughness: 1, metalness: 0 });
  patchMaterial(mat, { key: 'sand', caustic: 0.7 });
  const mesh = new THREE.Mesh(geo, mat);
  return mesh;
}

/* ---------- rocks ---------- */

function makeRockGeometry(rng: () => number): THREE.BufferGeometry {
  const geo = new THREE.IcosahedronGeometry(1, 2);
  geo.deleteAttribute('uv');
  geo.deleteAttribute('normal');
  const merged = mergeVertices(geo);
  const pos = merged.getAttribute('position');
  const a = rng() * 10;
  const b = rng() * 10;
  const colors = new Float32Array(pos.count * 3);
  for (let i = 0; i < pos.count; i++) {
    const v = new THREE.Vector3().fromBufferAttribute(pos, i).normalize();
    const n =
      0.18 * Math.sin(v.x * 3.1 + a) * Math.sin(v.y * 2.7 + b) +
      0.1 * Math.sin(v.z * 6.3 + a * 2) * Math.sin(v.x * 5.1 + b);
    v.multiplyScalar(1 + n);
    pos.setXYZ(i, v.x, v.y, v.z);
    const c = 0.75 + 0.25 * Math.sin(v.y * 4 + a);
    colors[i * 3] = c;
    colors[i * 3 + 1] = c;
    colors[i * 3 + 2] = c;
  }
  merged.setAttribute('color', new THREE.BufferAttribute(colors, 3));
  merged.computeVertexNormals();
  return merged;
}

export function createRocks(): THREE.Group {
  const group = new THREE.Group();
  const rng = makeRng(21);
  const mat = new THREE.MeshStandardMaterial({
    color: 0x6f7468,
    roughness: 0.95,
    vertexColors: true,
  });
  patchMaterial(mat, { key: 'rock', caustic: 0.25 });
  const geos = [makeRockGeometry(rng), makeRockGeometry(rng), makeRockGeometry(rng)];

  const add = (x: number, z: number, sx: number, sy: number, sz: number, gi: number) => {
    const m = new THREE.Mesh(geos[gi % geos.length], mat);
    m.position.set(x, terrainHeight(x, z) + sy * 0.25, z);
    m.scale.set(sx, sy, sz);
    m.rotation.y = rng() * Math.PI * 2;
    group.add(m);
  };
  add(0, 0, 1.5, 0.9, 1.3, 0);
  for (let i = 0; i < 22; i++) {
    const ang = rng() * Math.PI * 2;
    const rad = 1.8 + rng() * 6.5;
    const s = 0.25 + rng() * 0.5;
    add(Math.cos(ang) * rad, Math.sin(ang) * rad, s * 1.3, s * 0.8, s, i);
  }
  return group;
}

/* ---------- corals ---------- */

function branchingGeometry(rng: () => number, roots: number, maxLevel: number): THREE.BufferGeometry {
  const parts: THREE.BufferGeometry[] = [];
  const grow = (origin: THREE.Vector3, dir: THREE.Vector3, len: number, radius: number, level: number) => {
    const g = new THREE.CylinderGeometry(radius * 0.72, radius, len, 6, 1, true);
    g.translate(0, len / 2, 0);
    const q = new THREE.Quaternion().setFromUnitVectors(UP, dir);
    g.applyMatrix4(new THREE.Matrix4().compose(origin, q, new THREE.Vector3(1, 1, 1)));
    setConstantColor(g, 0.55 + 0.45 * (level / maxLevel));
    parts.push(g);
    if (level < maxLevel) {
      const end = origin.clone().addScaledVector(dir, len);
      const n = rng() < 0.4 ? 3 : 2;
      for (let i = 0; i < n; i++) {
        const nd = dir
          .clone()
          .add(new THREE.Vector3((rng() - 0.5) * 1.1, (rng() - 0.2) * 0.5, (rng() - 0.5) * 1.1))
          .normalize();
        nd.y += 0.2;
        nd.normalize();
        grow(end, nd, len * 0.74, radius * 0.7, level + 1);
      }
    }
  };
  for (let i = 0; i < roots; i++) {
    const a = (i / roots) * Math.PI * 2 + rng();
    const dir = new THREE.Vector3(Math.cos(a) * 0.35, 1, Math.sin(a) * 0.35).normalize();
    grow(new THREE.Vector3(Math.cos(a) * 0.08, 0, Math.sin(a) * 0.08), dir, 0.5, 0.08, 0);
  }
  return mergeGeometries(parts, false);
}

function brainGeometry(rng: () => number): THREE.BufferGeometry {
  const base = new THREE.IcosahedronGeometry(1, 5);
  base.deleteAttribute('uv');
  base.deleteAttribute('normal');
  const geo = mergeVertices(base);
  const pos = geo.getAttribute('position');
  const colors = new Float32Array(pos.count * 3);
  const a = rng() * 20;
  const v = new THREE.Vector3();
  for (let i = 0; i < pos.count; i++) {
    v.fromBufferAttribute(pos, i).normalize();
    const warp = 1.6 * Math.sin(v.y * 7 + a) + 1.2 * Math.sin(v.z * 6 - a);
    const f = Math.sin(v.x * 15 + warp + Math.sin(v.z * 9 + a) * 1.5);
    const ridge = Math.abs(f);
    const r = 1 - 0.07 * (1 - ridge);
    pos.setXYZ(i, v.x * r, Math.max(v.y * 0.75 * r, -0.15), v.z * r);
    const c = 0.6 + 0.4 * ridge;
    colors[i * 3] = c;
    colors[i * 3 + 1] = c;
    colors[i * 3 + 2] = c;
  }
  geo.setAttribute('color', new THREE.BufferAttribute(colors, 3));
  geo.computeVertexNormals();
  return geo;
}

function tubeGeometry(rng: () => number): THREE.BufferGeometry {
  const parts: THREE.BufferGeometry[] = [];
  const count = 9;
  for (let i = 0; i < count; i++) {
    const a = rng() * Math.PI * 2;
    const d = i === 0 ? 0 : 0.1 + rng() * 0.38;
    const h = 0.5 + rng() * 0.8;
    const r = 0.07 + rng() * 0.05;
    const tube = new THREE.CylinderGeometry(r, r * 0.8, h, 12, 1, true);
    setConstantColor(tube, 1);
    const cap = new THREE.CircleGeometry(r * 0.88, 12);
    cap.rotateX(-Math.PI / 2);
    cap.translate(0, h - 0.04, 0);
    setConstantColor(cap, 0.18);
    const g = mergeGeometries([tube, cap], false);
    g.translate(0, h / 2, 0);
    const lean = new THREE.Quaternion().setFromEuler(
      new THREE.Euler((rng() - 0.5) * 0.35, 0, (rng() - 0.5) * 0.35),
    );
    g.applyMatrix4(
      new THREE.Matrix4().compose(
        new THREE.Vector3(Math.cos(a) * d, 0, Math.sin(a) * d),
        lean,
        new THREE.Vector3(1, 1, 1),
      ),
    );
    parts.push(g);
  }
  return mergeGeometries(parts, false);
}

function tableGeometry(): THREE.BufferGeometry {
  const stem = new THREE.CylinderGeometry(0.12, 0.2, 0.6, 8, 1, true);
  stem.translate(0, 0.3, 0);
  setConstantColor(stem, 0.6);
  const top = new THREE.CylinderGeometry(1.1, 0.25, 0.3, 28, 3, false);
  const p = top.getAttribute('position');
  const colors = new Float32Array(p.count * 3);
  for (let i = 0; i < p.count; i++) {
    const x = p.getX(i);
    const z = p.getZ(i);
    const ang = Math.atan2(z, x);
    const rr = Math.hypot(x, z);
    const w = 1 + 0.08 * Math.sin(ang * 9) * Math.min(1, rr);
    p.setXYZ(i, x * w, p.getY(i) + 0.05 * Math.sin(ang * 5 + rr * 4) * rr, z * w);
    const c = 0.7 + 0.3 * Math.min(1, rr);
    colors[i * 3] = c;
    colors[i * 3 + 1] = c;
    colors[i * 3 + 2] = c;
  }
  top.setAttribute('color', new THREE.BufferAttribute(colors, 3));
  top.translate(0, 0.72, 0);
  return mergeGeometries([stem, top], false);
}

function makeFanTexture(): THREE.CanvasTexture {
  const c = document.createElement('canvas');
  c.width = 256;
  c.height = 256;
  const g = c.getContext('2d');
  if (!g) throw new Error('2d context unavailable');
  g.clearRect(0, 0, 256, 256);
  g.strokeStyle = '#ffffff';
  g.lineCap = 'round';
  const cx = 128;
  const cy = 250;
  for (let i = 0; i <= 12; i++) {
    const a = -Math.PI / 2 + (i / 12 - 0.5) * 2.3;
    g.lineWidth = 8;
    g.beginPath();
    g.moveTo(cx, cy);
    g.lineTo(cx + Math.cos(a) * 235, cy + Math.sin(a) * 235);
    g.stroke();
  }
  g.lineWidth = 6;
  for (let r = 50; r <= 230; r += 36) {
    g.beginPath();
    g.arc(cx, cy, r, -Math.PI / 2 - 1.15, -Math.PI / 2 + 1.15);
    g.stroke();
  }
  const tex = new THREE.CanvasTexture(c);
  tex.colorSpace = THREE.SRGBColorSpace;
  tex.anisotropy = 4;
  return tex;
}

function fanGeometry(): THREE.BufferGeometry {
  const g = new THREE.PlaneGeometry(1.7, 1.7, 12, 12);
  const p = g.getAttribute('position');
  for (let i = 0; i < p.count; i++) {
    const x = p.getX(i);
    const y = p.getY(i) + 0.85;
    p.setXYZ(i, x, y, 0.18 * Math.sin(x * 3.2) * y);
  }
  g.computeVertexNormals();
  return g;
}

export function createCorals(): THREE.Group {
  const group = new THREE.Group();
  const rng = makeRng(99);
  const fanTex = makeFanTexture();
  const fanGeo = fanGeometry();

  const solidMat = (color: number): THREE.MeshStandardMaterial => {
    const m = new THREE.MeshStandardMaterial({
      color,
      roughness: 0.75,
      vertexColors: true,
      side: THREE.DoubleSide,
    });
    patchMaterial(m, { key: 'coral', caustic: 0.3 });
    return m;
  };

  const place = (obj: THREE.Object3D, x: number, z: number, s: number, y?: number) => {
    obj.position.set(x, y ?? terrainHeight(x, z) - 0.03, z);
    obj.scale.setScalar(s);
    obj.rotation.y = rng() * Math.PI * 2;
    group.add(obj);
  };

  const branching = (x: number, z: number, s: number, color: number, y?: number) => {
    const m = new THREE.Mesh(branchingGeometry(rng, 3, 4), solidMat(color));
    place(m, x, z, s, y);
  };
  branching(0.1, 0.1, 0.9, 0xffa048, terrainHeight(0, 0) + 0.95);
  branching(-1.9, 1.3, 1.3, 0xff7a3d);
  branching(2.8, -1.4, 1.1, 0xe0409a);
  branching(-3.8, -2.8, 1.0, 0xf2d23c);
  branching(1.2, 4.0, 1.2, 0x8a63e0);
  branching(4.8, 2.6, 0.9, 0xff9aa8);

  const brain = (x: number, z: number, s: number, color: number) => {
    const m = new THREE.Mesh(brainGeometry(rng), solidMat(color));
    place(m, x, z, s, terrainHeight(x, z) + 0.35 * s);
  };
  brain(0.9, -2.4, 1.0, 0x8fbf4a);
  brain(-2.8, 3.2, 0.9, 0xd6a86a);
  brain(4.0, 0.2, 0.8, 0xe07a8a);
  brain(-0.8, 2.4, 0.6, 0x4fb8a8);
  brain(-5.6, 0.8, 1.1, 0xb8c24a);

  const fan = (x: number, z: number, s: number, color: number) => {
    const mat = new THREE.MeshStandardMaterial({
      color,
      map: fanTex,
      alphaTest: 0.3,
      roughness: 0.8,
      side: THREE.DoubleSide,
    });
    patchMaterial(mat, { key: 'fan', caustic: 0.25, swayAmp: 0.1 });
    const m = new THREE.Mesh(fanGeo, mat);
    m.frustumCulled = false;
    place(m, x, z, s);
  };
  fan(-4.7, -0.6, 1.4, 0xb04ad0);
  fan(2.0, -4.0, 1.3, 0xe0384a);
  fan(-1.2, -4.8, 1.1, 0xf08a30);
  fan(5.2, -1.2, 1.0, 0xd04aa0);

  const tube = (x: number, z: number, s: number, color: number) => {
    const m = new THREE.Mesh(tubeGeometry(rng), solidMat(color));
    place(m, x, z, s);
  };
  tube(2.0, 1.1, 1.0, 0xf2c43a);
  tube(-2.4, -1.3, 1.1, 0x4a7fe0);
  tube(3.8, -3.4, 1.0, 0xe8603a);
  tube(-0.2, 5.0, 0.9, 0x38b8d8);

  const table = new THREE.Mesh(tableGeometry(), solidMat(0x9ab86a));
  place(table, -5.6, -3.0, 1.3);
  const table2 = new THREE.Mesh(tableGeometry(), solidMat(0xd0a060));
  place(table2, 5.8, 4.0, 1.0);

  return group;
}

/* ---------- seaweed and anemones ---------- */

export function createPlants(): THREE.Group {
  const group = new THREE.Group();
  const rng = makeRng(1234);
  const m4 = new THREE.Matrix4();
  const q = new THREE.Quaternion();
  const e = new THREE.Euler();
  const col = new THREE.Color();

  // Seaweed blades
  const bladeGeo = new THREE.PlaneGeometry(1, 1, 1, 8);
  const bp = bladeGeo.getAttribute('position');
  for (let i = 0; i < bp.count; i++) {
    const y = bp.getY(i) + 0.5;
    bp.setXYZ(i, bp.getX(i) * 0.16 * (1 - 0.7 * y), y, 0);
  }
  bladeGeo.computeVertexNormals();
  const clusters = 11;
  const perCluster = 24;
  const bladeMat = new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: 0.7, side: THREE.DoubleSide });
  patchMaterial(bladeMat, { key: 'weed', caustic: 0.2, swayAmp: 0.4 });
  const blades = new THREE.InstancedMesh(bladeGeo, bladeMat, clusters * perCluster);
  blades.frustumCulled = false;
  let bi = 0;
  for (let c = 0; c < clusters; c++) {
    const ca = rng() * Math.PI * 2;
    const cr = 2.5 + rng() * 6;
    const cx = Math.cos(ca) * cr;
    const cz = Math.sin(ca) * cr;
    const hue = 0.22 + rng() * 0.1;
    for (let k = 0; k < perCluster; k++) {
      const a = rng() * Math.PI * 2;
      const d = Math.sqrt(rng()) * 0.55;
      const x = cx + Math.cos(a) * d;
      const z = cz + Math.sin(a) * d;
      const h = 0.9 + rng() * 1.3;
      e.set((rng() - 0.5) * 0.3, rng() * Math.PI * 2, (rng() - 0.5) * 0.3);
      q.setFromEuler(e);
      m4.compose(new THREE.Vector3(x, terrainHeight(x, z) - 0.02, z), q, new THREE.Vector3(1.3, h, 1));
      blades.setMatrixAt(bi, m4);
      col.setHSL(hue + rng() * 0.05, 0.55, 0.28 + rng() * 0.12);
      blades.setColorAt(bi, col);
      bi++;
    }
  }
  group.add(blades);

  // Anemones
  const tentGeo = new THREE.CylinderGeometry(0.008, 0.03, 0.5, 5, 5, true);
  tentGeo.translate(0, 0.25, 0);
  const anemones = [
    { x: 1.0, z: -0.9, hue: 0.92 },
    { x: -1.6, z: -2.4, hue: 0.07 },
    { x: 3.4, z: 2.0, hue: 0.78 },
    { x: -3.4, z: 0.8, hue: 0.95 },
    { x: 0.2, z: 3.2, hue: 0.12 },
    { x: -0.6, z: -3.4, hue: 0.85 },
  ];
  const perAnem = 36;
  const tentMat = new THREE.MeshStandardMaterial({
    color: 0xffffff,
    roughness: 0.6,
    side: THREE.DoubleSide,
    emissive: 0x200818,
  });
  patchMaterial(tentMat, { key: 'tent', caustic: 0.2, swayAmp: 1.1 });
  const tents = new THREE.InstancedMesh(tentGeo, tentMat, anemones.length * perAnem);
  tents.frustumCulled = false;
  const baseMat = new THREE.MeshStandardMaterial({ color: 0x884466, roughness: 0.8 });
  patchMaterial(baseMat, { key: 'abase', caustic: 0.2 });
  let ti = 0;
  for (const an of anemones) {
    const y0 = terrainHeight(an.x, an.z);
    const base = new THREE.Mesh(new THREE.CylinderGeometry(0.3, 0.38, 0.2, 14), baseMat);
    base.position.set(an.x, y0 + 0.05, an.z);
    group.add(base);
    for (let k = 0; k < perAnem; k++) {
      const a = rng() * Math.PI * 2;
      const d = Math.sqrt(rng()) * 0.27;
      const tilt = 0.15 + d * 1.6 + rng() * 0.2;
      e.set(Math.sin(a) * tilt, 0, -Math.cos(a) * tilt);
      q.setFromEuler(e);
      const s = 0.7 + rng() * 0.6;
      m4.compose(
        new THREE.Vector3(an.x + Math.cos(a) * d, y0 + 0.12, an.z + Math.sin(a) * d),
        q,
        new THREE.Vector3(1, s, 1),
      );
      tents.setMatrixAt(ti, m4);
      col.setHSL(an.hue + (rng() - 0.5) * 0.05, 0.7, 0.55 + rng() * 0.15);
      tents.setColorAt(ti, col);
      ti++;
    }
  }
  group.add(tents);

  return group;
}

import * as THREE from 'three';
import { mergeGeometries } from 'three/examples/jsm/utils/BufferGeometryUtils.js';
import { makeRng, patchMaterial, terrainHeight } from './util';

/* ---------- fish ---------- */

function fishGeometry(): THREE.BufferGeometry {
  const body = new THREE.SphereGeometry(1, 16, 12);
  body.scale(0.28, 0.42, 0.9);
  {
    const p = body.getAttribute('position');
    const c = new Float32Array(p.count * 3);
    for (let i = 0; i < p.count; i++) {
      const y = p.getY(i);
      const z = p.getZ(i);
      let k = 0.8 + 0.2 * (y / 0.42);
      const band = THREE.MathUtils.smoothstep(Math.sin(z * 6.5), 0.55, 0.85);
      k *= 1 - 0.5 * band;
      c[i * 3] = k;
      c[i * 3 + 1] = k;
      c[i * 3 + 2] = k;
    }
    body.setAttribute('color', new THREE.BufferAttribute(c, 3));
  }

  const flat = (g: THREE.BufferGeometry, k: number) => {
    const n = g.getAttribute('position').count;
    g.setAttribute('color', new THREE.BufferAttribute(new Float32Array(n * 3).fill(k), 3));
  };

  const tail = new THREE.ConeGeometry(0.4, 0.6, 4, 1, false);
  tail.rotateX(Math.PI / 2);
  tail.scale(0.12, 1, 1);
  tail.translate(0, 0, -1.2);
  flat(tail, 0.75);

  const dorsal = new THREE.ConeGeometry(0.3, 0.7, 3, 1, false);
  dorsal.rotateX(-Math.PI / 2 + 0.0);
  dorsal.rotateX(Math.PI / 2); // keep apex up
  dorsal.scale(0.1, 0.7, 1.5);
  dorsal.rotateX(0.6);
  dorsal.translate(0, 0.5, -0.15);
  flat(dorsal, 0.7);

  return mergeGeometries([body, tail, dorsal], false);
}

export type PathFn = (t: number, out: THREE.Vector3) => void;

export interface FishGroup {
  mesh: THREE.InstancedMesh;
  update: (t: number) => void;
}

function makeFishMesh(count: number, geo: THREE.BufferGeometry, rng: () => number): THREE.InstancedMesh {
  const mat = new THREE.MeshStandardMaterial({
    color: 0xffffff,
    vertexColors: true,
    roughness: 0.45,
    metalness: 0.1,
    side: THREE.DoubleSide,
  });
  patchMaterial(mat, { key: 'fish', caustic: 0.15, wag: true });
  const mesh = new THREE.InstancedMesh(geo, mat, count);
  mesh.frustumCulled = false;
  const phase = new Float32Array(count);
  for (let i = 0; i < count; i++) phase[i] = rng() * Math.PI * 2;
  geo.setAttribute('aPhase', new THREE.InstancedBufferAttribute(phase, 1));
  return mesh;
}

const dummy = new THREE.Object3D();
const pA = new THREE.Vector3();
const pB = new THREE.Vector3();

function placeFish(mesh: THREE.InstancedMesh, i: number, a: THREE.Vector3, b: THREE.Vector3, scale: number): void {
  dummy.position.copy(a);
  dummy.lookAt(b);
  dummy.scale.setScalar(scale);
  dummy.updateMatrix();
  mesh.setMatrixAt(i, dummy.matrix);
}

export function createSchool(count: number): FishGroup {
  const rng = makeRng(555);
  const geo = fishGeometry();
  const mesh = makeFishMesh(count, geo, rng);
  const col = new THREE.Color();
  const palette = [0xffb830, 0xff7a2a, 0x40a8ff, 0xffe45a, 0xff9a60];
  const offsets: THREE.Vector3[] = [];
  const lags: number[] = [];
  const ph: number[][] = [];
  const scales: number[] = [];
  for (let i = 0; i < count; i++) {
    const base = new THREE.Color(palette[Math.floor(rng() * 3.2)]);
    col.copy(base).offsetHSL((rng() - 0.5) * 0.03, 0, (rng() - 0.5) * 0.08);
    mesh.setColorAt(i, col);
    const v = new THREE.Vector3(rng() - 0.5, (rng() - 0.5) * 0.6, rng() - 0.5).multiplyScalar(3.2);
    offsets.push(v);
    lags.push(rng() * 0.9);
    ph.push([rng() * 6.28, rng() * 6.28, rng() * 6.28]);
    scales.push(0.15 + rng() * 0.04);
  }

  const centre = (t: number, out: THREE.Vector3) => {
    out.set(
      5.2 * Math.cos(0.27 * t) + 1.5 * Math.sin(0.6 * t),
      3.0 + 0.5 * Math.sin(0.33 * t),
      4.4 * Math.sin(0.27 * t + 0.5) + 1.0,
    );
  };
  const fishPos = (i: number, t: number, out: THREE.Vector3) => {
    centre(t - lags[i], out);
    const o = offsets[i];
    const p = ph[i];
    out.x += o.x + 0.5 * Math.sin(0.9 * t + p[0]);
    out.y += o.y + 0.25 * Math.sin(0.7 * t + p[1]);
    out.z += o.z + 0.5 * Math.sin(0.8 * t + p[2]);
    const minY = terrainHeight(out.x, out.z) + 2.0;
    if (out.y < minY) out.y = minY;
  };

  return {
    mesh,
    update: (t: number) => {
      for (let i = 0; i < count; i++) {
        fishPos(i, t, pA);
        fishPos(i, t + 0.1, pB);
        placeFish(mesh, i, pA, pB, scales[i]);
      }
      mesh.instanceMatrix.needsUpdate = true;
    },
  };
}

interface Loner {
  path: PathFn;
  scale: number;
  color: number;
}

export function createLoners(): FishGroup {
  const rng = makeRng(808);
  const geo = fishGeometry();
  const loners: Loner[] = [
    {
      path: (t, o) => o.set(8.5 * Math.cos(0.16 * t), 1.9 + 0.4 * Math.sin(0.4 * t), 6.5 * Math.sin(0.16 * t)),
      scale: 0.5,
      color: 0x2f6fe0,
    },
    {
      path: (t, o) =>
        o.set(4.8 * Math.cos(-0.21 * t + 2), 2.5 + 0.3 * Math.sin(0.5 * t), 3.8 * Math.sin(-0.21 * t + 2)),
      scale: 0.42,
      color: 0xffd02a,
    },
    {
      path: (t, o) => o.set(7.5 * Math.cos(0.12 * t + 1), 3.9 + 0.5 * Math.sin(0.35 * t), 5.5 * Math.sin(0.24 * t)),
      scale: 0.6,
      color: 0xe04a3a,
    },
    {
      path: (t, o) =>
        o.set(10.5 * Math.cos(-0.1 * t + 4), 1.6 + 0.3 * Math.sin(0.3 * t), 9 * Math.sin(-0.1 * t + 4)),
      scale: 0.75,
      color: 0x7fb0a8,
    },
  ];
  const mesh = makeFishMesh(loners.length, geo, rng);
  const col = new THREE.Color();
  loners.forEach((l, i) => mesh.setColorAt(i, col.set(l.color)));
  return {
    mesh,
    update: (t: number) => {
      loners.forEach((l, i) => {
        l.path(t, pA);
        l.path(t + 0.1, pB);
        const minY = terrainHeight(pA.x, pA.z) + 1.4;
        if (pA.y < minY) {
          pA.y = minY;
          pB.y = minY;
        }
        placeFish(mesh, i, pA, pB, l.scale);
      });
      mesh.instanceMatrix.needsUpdate = true;
    },
  };
}

/* ---------- bubbles and particles ---------- */

function bubbleTexture(): THREE.CanvasTexture {
  const c = document.createElement('canvas');
  c.width = 64;
  c.height = 64;
  const g = c.getContext('2d');
  if (!g) throw new Error('2d context unavailable');
  const grad = g.createRadialGradient(32, 32, 4, 32, 32, 30);
  grad.addColorStop(0, 'rgba(220,255,255,0.08)');
  grad.addColorStop(0.75, 'rgba(220,255,255,0.25)');
  grad.addColorStop(0.92, 'rgba(255,255,255,0.95)');
  grad.addColorStop(1, 'rgba(255,255,255,0)');
  g.fillStyle = grad;
  g.fillRect(0, 0, 64, 64);
  g.fillStyle = 'rgba(255,255,255,0.9)';
  g.beginPath();
  g.arc(22, 21, 4, 0, Math.PI * 2);
  g.fill();
  const t = new THREE.CanvasTexture(c);
  t.colorSpace = THREE.SRGBColorSpace;
  return t;
}

function softTexture(): THREE.CanvasTexture {
  const c = document.createElement('canvas');
  c.width = 32;
  c.height = 32;
  const g = c.getContext('2d');
  if (!g) throw new Error('2d context unavailable');
  const grad = g.createRadialGradient(16, 16, 0, 16, 16, 16);
  grad.addColorStop(0, 'rgba(255,255,255,1)');
  grad.addColorStop(1, 'rgba(255,255,255,0)');
  g.fillStyle = grad;
  g.fillRect(0, 0, 32, 32);
  const t = new THREE.CanvasTexture(c);
  t.colorSpace = THREE.SRGBColorSpace;
  return t;
}

export function createBubbles(): { object: THREE.Points; update: (t: number) => void } {
  const rng = makeRng(31);
  const emitters = [
    [-1.2, 0.8],
    [2.6, -1.0],
    [-3.6, -2.6],
    [1.0, 3.8],
    [4.6, 2.4],
    [-2.0, -4.2],
  ];
  const per = 14;
  const n = emitters.length * per;
  const geo = new THREE.BufferGeometry();
  const arr = new Float32Array(n * 3);
  geo.setAttribute('position', new THREE.BufferAttribute(arr, 3));
  const speed: number[] = [];
  const off: number[] = [];
  const ph: number[] = [];
  const spread: number[][] = [];
  for (let i = 0; i < n; i++) {
    speed.push(0.05 + rng() * 0.04);
    off.push(rng());
    ph.push(rng() * 6.28);
    spread.push([(rng() - 0.5) * 0.5, (rng() - 0.5) * 0.5]);
  }
  const mat = new THREE.PointsMaterial({
    map: bubbleTexture(),
    size: 0.32,
    transparent: true,
    depthWrite: false,
    sizeAttenuation: true,
  });
  const pts = new THREE.Points(geo, mat);
  pts.frustumCulled = false;
  const H = 11;
  return {
    object: pts,
    update: (t: number) => {
      for (let i = 0; i < n; i++) {
        const e = emitters[Math.floor(i / per)];
        const f = (t * speed[i] + off[i]) % 1;
        const y = terrainHeight(e[0], e[1]) + 0.4 + f * H;
        const wob = 0.12 + 0.25 * f;
        arr[i * 3] = e[0] + spread[i][0] + Math.sin(t * 1.3 + ph[i]) * wob;
        arr[i * 3 + 1] = y;
        arr[i * 3 + 2] = e[1] + spread[i][1] + Math.cos(t * 1.1 + ph[i]) * wob;
      }
      geo.getAttribute('position').needsUpdate = true;
    },
  };
}

export function createSnow(): { object: THREE.Points; update: (t: number) => void } {
  const rng = makeRng(77);
  const n = 220;
  const span = new THREE.Vector3(26, 9, 26);
  const base: number[] = [];
  const vel: number[] = [];
  for (let i = 0; i < n; i++) {
    base.push(rng() * span.x, rng() * span.y, rng() * span.z);
    vel.push((rng() - 0.5) * 0.15, 0.03 + rng() * 0.06, (rng() - 0.5) * 0.15);
  }
  const arr = new Float32Array(n * 3);
  const geo = new THREE.BufferGeometry();
  geo.setAttribute('position', new THREE.BufferAttribute(arr, 3));
  const mat = new THREE.PointsMaterial({
    map: softTexture(),
    size: 0.16,
    color: 0xd8fff0,
    transparent: true,
    opacity: 0.55,
    depthWrite: false,
  });
  const pts = new THREE.Points(geo, mat);
  pts.frustumCulled = false;
  const wrap = (v: number, s: number) => ((v % s) + s) % s;
  return {
    object: pts,
    update: (t: number) => {
      for (let i = 0; i < n; i++) {
        arr[i * 3] = wrap(base[i * 3] + vel[i * 3] * t + Math.sin(t * 0.3 + i) * 0.3, span.x) - span.x / 2;
        arr[i * 3 + 1] = wrap(base[i * 3 + 1] + vel[i * 3 + 1] * t, span.y) + 0.3;
        arr[i * 3 + 2] = wrap(base[i * 3 + 2] + vel[i * 3 + 2] * t, span.z) - span.z / 2;
      }
      geo.getAttribute('position').needsUpdate = true;
    },
  };
}

/* ---------- light shafts and backdrop ---------- */

function beamTexture(): THREE.CanvasTexture {
  const w = 64;
  const h = 128;
  const c = document.createElement('canvas');
  c.width = w;
  c.height = h;
  const g = c.getContext('2d');
  if (!g) throw new Error('2d context unavailable');
  const img = g.createImageData(w, h);
  for (let y = 0; y < h; y++) {
    for (let x = 0; x < w; x++) {
      const u = (x / (w - 1)) * 2 - 1;
      const bell = Math.exp(-u * u * 4.5);
      const fade = Math.pow(1 - y / (h - 1), 0.9);
      const idx = (y * w + x) * 4;
      img.data[idx] = 255;
      img.data[idx + 1] = 255;
      img.data[idx + 2] = 255;
      img.data[idx + 3] = Math.round(255 * bell * fade);
    }
  }
  g.putImageData(img, 0, 0);
  const t = new THREE.CanvasTexture(c);
  t.colorSpace = THREE.SRGBColorSpace;
  return t;
}

export function createBeams(): { object: THREE.Group; update: (t: number) => void } {
  const rng = makeRng(404);
  const group = new THREE.Group();
  const tex = beamTexture();
  const beams: { mat: THREE.MeshBasicMaterial; ph: number; base: number }[] = [];
  const geoCache = new Map<number, THREE.PlaneGeometry>();
  for (let i = 0; i < 8; i++) {
    const width = 2.5 + rng() * 2.5;
    const ang = rng() * Math.PI * 2;
    const rad = 2 + rng() * 9;
    const x = Math.cos(ang) * rad;
    const z = Math.sin(ang) * rad;
    const base = 0.09 + rng() * 0.06;
    const ph = rng() * 6.28;
    const yaw = rng() * Math.PI;
    for (let k = 0; k < 2; k++) {
      const key = Math.round(width * 100);
      let geo = geoCache.get(key);
      if (!geo) {
        geo = new THREE.PlaneGeometry(width, 18);
        geo.translate(0, -9, 0);
        geoCache.set(key, geo);
      }
      const mat = new THREE.MeshBasicMaterial({
        map: tex,
        color: 0xa8ffe8,
        transparent: true,
        opacity: base,
        blending: THREE.AdditiveBlending,
        depthWrite: false,
        side: THREE.DoubleSide,
        fog: false,
      });
      const m = new THREE.Mesh(geo, mat);
      m.rotation.order = 'ZYX';
      m.rotation.z = 0.22;
      m.rotation.y = yaw + k * Math.PI * 0.5;
      m.position.set(x, 14, z);
      m.frustumCulled = false;
      group.add(m);
      beams.push({ mat, ph, base });
    }
  }
  return {
    object: group,
    update: (t: number) => {
      for (const b of beams) b.mat.opacity = b.base * (0.65 + 0.35 * Math.sin(t * 0.5 + b.ph));
    },
  };
}

export function createBackdrop(fogColor: THREE.Color): THREE.Mesh {
  const mat = new THREE.ShaderMaterial({
    side: THREE.BackSide,
    depthWrite: false,
    fog: false,
    uniforms: {
      uLow: { value: fogColor.clone() },
      uHigh: { value: new THREE.Color(0x4fd6d0) },
    },
    vertexShader: /* glsl */ `
      varying vec3 vDir;
      void main() {
        vDir = normalize(position);
        gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
      }
    `,
    fragmentShader: /* glsl */ `
      uniform vec3 uLow;
      uniform vec3 uHigh;
      varying vec3 vDir;
      void main() {
        float k = smoothstep(0.0, 0.75, vDir.y);
        gl_FragColor = vec4(mix(uLow, uHigh, k * 0.85), 1.0);
        #include <colorspace_fragment>
      }
    `,
  });
  const mesh = new THREE.Mesh(new THREE.SphereGeometry(60, 24, 16), mat);
  mesh.renderOrder = -10;
  mesh.frustumCulled = false;
  return mesh;
}

